/**
 * Generate build-time constants from package.json
 * Run this before svelte-package to bake values into the library
 */

import { readFileSync, writeFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const pkg = JSON.parse(readFileSync(join(__dirname, '../package.json'), 'utf-8'));

const constants = `// Auto-generated file - do not edit manually
// Generated by scripts/generate-constants.js

export const VERSION = ${JSON.stringify(pkg.version)};
export const PACKAGE_NAME = ${JSON.stringify(pkg.name)};
export const AUTHOR = ${JSON.stringify(typeof pkg.author === 'string' ? pkg.author : pkg.author?.name || '')};
export const LICENSE = ${JSON.stringify(pkg.license || '')};
export const REPOSITORY = ${JSON.stringify(typeof pkg.repository === 'string' ? pkg.repository : pkg.repository?.url || '')};
export const HOMEPAGE = ${JSON.stringify(pkg.homepage || '')};
`;

const outputPath = join(__dirname, '../src/lib/constants.generated.ts');
writeFileSync(outputPath, constants);
console.log(`Generated constants at ${outputPath}`);
console.log(`  VERSION: ${pkg.version}`);
console.log(`  PACKAGE_NAME: ${pkg.name}`);
